<?php
require_once __DIR__ . '/../includes/table_admin.php';$active_menu='database';$table=(string)($_GET['table']??'');if(!valid_table_name($table)){set_flash('danger','Select a valid database table.');redirect('database/index.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf_or_redirect('database/structure.php?table='.urlencode($table));$column=posted('column_name');$type=approved_column_type(posted('column_type'),posted('column_length'));$nullable=isset($_POST['nullable']);$default=posted('default_value');if(!safe_identifier($column)||!$type){$_SESSION['column_error']='Enter a valid column name and approved data type.';}elseif(in_array($column,array_column(all_rows('DESCRIBE '.quoted_identifier($table)),'Field'),true)){$_SESSION['column_error']='A column with that name already exists.';}elseif($default!=='' && strlen($default)>200){$_SESSION['column_error']='Default value is too long.';}else{try{$sql='ALTER TABLE '.quoted_identifier($table).' ADD COLUMN '.quoted_identifier($column).' '.$type.($nullable?' NULL':' NOT NULL');if($default!=='')$sql.=' DEFAULT '.db()->quote($default);db()->exec($sql);set_flash('success','Column '.$column.' added successfully.');redirect('database/structure.php?table='.urlencode($table));}catch(PDOException $exception){$_SESSION['column_error']='The column could not be added. Check the selected type and default value.';}}}
$columns=all_rows('DESCRIBE '.quoted_identifier($table));$error=$_SESSION['column_error']??'';unset($_SESSION['column_error']);$page_title='Table Structure: '.$table;require __DIR__.'/../includes/header.php';
?>
<div class="d-flex justify-content-between align-items-center mb-3"><p class="text-secondary mb-0">Table: <code><?=e($table)?></code></p><a class="btn btn-outline-secondary" href="<?=e(app_url('database/index.php'))?>">Back to tables</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card shadow-sm table-card mb-4"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Column</th><th>Type</th><th>Null</th><th>Key</th><th>Default</th><th>Extra</th><th class="text-end">Action</th></tr></thead><tbody><?php foreach($columns as $column):?><tr><td><code><?=e($column['Field'])?></code></td><td><?=e($column['Type'])?></td><td><?=e($column['Null'])?></td><td><?=e($column['Key'])?></td><td><?=e((string)$column['Default'])?></td><td><?=e($column['Extra'])?></td><td class="text-end"><?php if($column['Key']!=='PRI'):?><form class="d-inline" method="post" action="<?=e(app_url('database/delete_column.php'))?>"><input type="hidden" name="table" value="<?=e($table)?>"><input type="hidden" name="column" value="<?=e($column['Field'])?>"><input type="hidden" name="confirm" value="1"><?=csrf_input()?><button class="btn btn-sm btn-outline-danger" data-confirm="Remove column '<?=e($column['Field'])?>' from table '<?=e($table)?>'? All values in this column will be lost.">Remove</button></form><?php else:?><span class="text-secondary small">Primary key protected</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><div class="card form-card shadow-sm"><div class="card-body p-4"><h2 class="h5">Add a column</h2><form method="post"><div class="row"><div class="col-md-4 mb-3"><label class="form-label">Column name</label><input class="form-control" name="column_name" pattern="[A-Za-z][A-Za-z0-9_]{0,63}" required></div><div class="col-md-3 mb-3"><label class="form-label">Data type</label><select class="form-select" name="column_type"><option>VARCHAR</option><option>CHAR</option><option>TEXT</option><option>INT</option><option>BIGINT</option><option>DECIMAL(10,2)</option><option>DATE</option><option>DATETIME</option><option>BOOLEAN</option></select></div><div class="col-md-2 mb-3"><label class="form-label">Length</label><input class="form-control" name="column_length" type="number" min="1" max="255" placeholder="VARCHAR only"></div><div class="col-md-3 mb-3"><label class="form-label">Default value</label><input class="form-control" name="default_value" maxlength="200" placeholder="Optional"></div><div class="col-12 mb-3"><div class="form-check"><input class="form-check-input" type="checkbox" name="nullable" id="nullable"><label class="form-check-label" for="nullable">Allow NULL values</label></div></div></div><?=csrf_input()?><button class="btn btn-primary">Add column</button></form></div></div><?php require __DIR__.'/../includes/footer.php';
